pipeline {
  agent { label 'windows-ci' }
  options {
    skipDefaultCheckout()
    disableConcurrentBuilds()
    timeout(time: 30, unit: 'MINUTES')
    skipStagesAfterUnstable()
  }
  stages {
    stage('Checkout') { steps { checkout scm } }
    stage('Build') {
      steps {
        bat 'cmake --preset windows-ci'
        bat 'cmake --build --preset windows-ci'
      }
    }
    stage('Test') {
      steps {
        powershell 'if (Test-Path -LiteralPath "out/windows-ci/results.xml") { Remove-Item -LiteralPath "out/windows-ci/results.xml" -ErrorAction Stop }'
        bat 'ctest --preset windows-ci --no-tests=error --output-on-failure --output-junit "%WORKSPACE%/out/windows-ci/results.xml"'
      }
      post {
        always {
          junit testResults: 'out/windows-ci/results.xml', allowEmptyResults: false
        }
      }
    }
  }
}
// 검사한 산출물을 대상으로, 별도 승인과 권한을 갖춘 작업에서 서명하고 릴리스한다.

{
  "version": 3,
  "cmakeMinimumRequired": {
    "major": 3,
    "minor": 21,
    "patch": 0
  },
  "configurePresets": [
    {
      "name": "windows-ci",
      "generator": "Visual Studio 17 2022",
      "architecture": "x64",
      "binaryDir": "${sourceDir}/out/windows-ci"
    }
  ],
  "buildPresets": [
    {
      "name": "windows-ci",
      "configurePreset": "windows-ci",
      "configuration": "Release"
    }
  ],
  "testPresets": [
    {
      "name": "windows-ci",
      "configurePreset": "windows-ci",
      "configuration": "Release",
      "output": {
        "outputOnFailure": true
      },
      "execution": {
        "noTestsAction": "error"
      }
    }
  ]
}

#include <gtest/gtest.h>
int shippingFee(int amount) { return amount >= 20000 ? 0 : 3000; }
TEST(Shipping, BelowThreshold) { EXPECT_EQ(shippingFee(19999), 3000); }
TEST(Shipping, AtThreshold) { EXPECT_EQ(shippingFee(20000), 0); }
TEST(Shipping, AboveThreshold) { EXPECT_EQ(shippingFee(30000), 0); }

cmake --preset windows-ci
if ($LASTEXITCODE -ne 0) { throw "CMake 구성 실패" }
cmake --build --preset windows-ci
if ($LASTEXITCODE -ne 0) { throw "C++ 빌드 실패" }
$reportPath = Join-Path (Get-Location) 'out/windows-ci/results.xml'
if (Test-Path -LiteralPath $reportPath) { Remove-Item -LiteralPath $reportPath -ErrorAction Stop }
ctest --preset windows-ci --no-tests=error --output-on-failure --output-junit "$reportPath"
if ($LASTEXITCODE -ne 0) { throw "CTest 검사 실패" }
